-- 1. Insert 40 Master Timepieces
INSERT INTO watches (
    id, num, brand_id, brand_name, model, price, original_price, rating, reviews_count,
    image_url, category_id, category_name, gender, movement, style, case_size,
    strap, dial, material, water_resistance, badge, tagline, description,
    ai_match_score, ai_reason, stock_count, is_active
) VALUES
('WRT-001', '01', 'brand-auren', 'AUREN', 'Atlas Black', 4999.00, 6499.00, 4.8, 142, '/assets/products/watch-01.png', 'cat-men', 'Men', 'Men', 'Quartz', 'Minimal', '40mm', 'Black Leather', 'Matte Black', 'Stainless Steel', '50m', 'Best Seller', 'Stripped-back monochrome precision for modern minimalism.', 'The AUREN Atlas Black strips horology down to its purest essentials. Featuring an ultra-slim 40mm surgical-grade stainless steel case finished in brushed obsidian, an unblemished matte black dial with hairline indices, and a supple vegetable-tanned Italian calfskin strap.', 98, 'Understated obsidian aesthetic pairs seamlessly with both monochrome tailored suiting and minimalist weekend wear.', 15, TRUE),
('WRT-002', '02', 'brand-auren', 'AUREN', 'Meridian Silver', 5499.00, 6999.00, 4.7, 98, '/assets/products/watch-02.png', 'cat-men', 'Men', 'Men', 'Quartz', 'Classic', '41mm', 'Silver Mesh', 'Sunray Silver', 'Stainless Steel', '50m', 'Trending', 'Fluid Milanese elegance reflecting metropolitan light.', 'Crafted for those who appreciate understated brilliance, the Meridian Silver pairs an architectural sunray silver dial with a fluid Milanese mesh strap that adjusts smoothly to any wrist size.', 94, 'High-luminance silver finish complements formal shirting while offering breathable mesh comfort for all-day desk wear.', 15, TRUE),
('WRT-003', '03', 'brand-auren', 'AUREN', 'Heritage Gold', 6999.00, 8999.00, 4.9, 215, '/assets/products/watch-03.png', 'cat-men', 'Men', 'Men', 'Quartz', 'Dress', '39mm', 'Rich Brown Leather', 'Champagne Gold', 'Gold PVD Steel', '30m', 'Luxury Pick', 'Warm champagne tones reminiscent of vintage heirloom timepieces.', 'With its warm champagne sunburst dial, hand-polished gold PVD case, and deep mahogany alligator-grain leather strap, the Heritage Gold embodies timeless mid-century poise.', 92, 'Rich warm gold dial harmonizes with earth-toned outerwear, blazers, and evening dress codes.', 15, TRUE),
('WRT-004', '04', 'brand-auren', 'AUREN', 'Edge Blue', 4499.00, 5999.00, 4.6, 76, '/assets/products/watch-04.png', 'cat-men', 'Men', 'Men', 'Quartz', 'Casual', '42mm', 'Midnight Blue Leather', 'Sunray Royal Blue', 'Stainless Steel', '50m', 'New', 'Deep ocean contrast that catches ambient light with subtlety.', 'The Edge Blue showcases an electric royal blue sunray dial framed in a sharp chamfered bezel. Designed as a daily driver with elevated character.', 90, 'Vibrant royal dial adds a tasteful pop of contrast to neutral outfits without looking loud.', 15, TRUE),
('WRT-005', '05', 'brand-auren', 'AUREN', 'Regent Green', 14999.00, 18999.00, 4.9, 310, '/assets/products/watch-05.png', 'cat-men', 'Men', 'Men', 'Automatic', 'Premium', '41mm', 'Solid Link Steel', 'Emerald Green', '316L Stainless Steel', '100m', 'Editorial Choice', 'Lush emerald lacquer dial driven by an exhibition-back automatic caliber.', 'The flagship of the Auren line. Featuring an exhibition caseback revealing an automatic movement with a 42-hour power reserve, sapphire crystal, and an intoxicating deep forest emerald dial.', 96, 'High-spec automatic movement paired with a coveted green dial that makes a subtle yet unmistakable statement of refinement.', 15, TRUE),
('WRT-006', '06', 'brand-auren', 'AUREN', 'Chrono Steel', 8999.00, 11499.00, 4.8, 184, '/assets/products/watch-06.png', 'cat-men', 'Men', 'Men', 'Quartz', 'Chronograph', '43mm', 'Stainless Steel', 'Tri-Compax Black', 'Stainless Steel', '100m', 'Popular', 'Instrument-grade tri-compax chronograph with tactile pushers.', 'Engineered with three precision sub-dials measuring 24 hours, minutes, and split-seconds. The solid brushed 3-link bracelet gives it a commanding presence on the wrist.', 91, 'Provides sporty functionality with a clean executive aesthetic suitable for meetings and travel.', 15, TRUE),
('WRT-007', '07', 'brand-auren', 'AUREN', 'Terra Brown', 5999.00, 7499.00, 4.7, 88, '/assets/products/watch-07.png', 'cat-men', 'Men', 'Men', 'Quartz', 'Casual', '40mm', 'Espresso Leather', 'Warm Terra Brown', 'Rose Gold PVD Steel', '50m', 'Staff Pick', 'Warm mocha accents crafted for autumnal layers and casual suiting.', 'A rich tobacco dial matched with warm bronze-gold hardware and handcrafted textured leather. Perfect for coffee shop work sessions or evening dinner dates.', 89, 'Earthy tones lend an organic, tactile warmth to linen shirts and casual knitwear.', 15, TRUE),
('WRT-008', '08', 'brand-auren', 'AUREN', 'Eclipse Black', 7499.00, 9499.00, 4.8, 120, '/assets/products/watch-08.png', 'cat-men', 'Men', 'Men', 'Quartz', 'Dress', '40mm', 'Black Mesh Steel', 'Deep Obsidian', 'PVD Matte Black', '50m', 'Limited', 'Shadowy all-black silhouette engineered for cocktail hours.', 'Every millimeter of the Eclipse Black is treated with a durable matte DLC coating. The pitch-black dial reflects only the subtlest glint on the polished faceted hour hands.', 93, 'Flawless stealth profile that disappears under tuxedo cuffs while commanding attention upon closer glance.', 15, TRUE),
('WRT-009', '09', 'brand-vela', 'VELA', 'Luna Pearl', 5999.00, 7999.00, 4.9, 167, '/assets/products/watch-09.png', 'cat-women', 'Women', 'Women', 'Quartz', 'Dress', '34mm', 'Two-Tone Rose & Silver', 'Mother of Pearl', 'Rose Gold & Steel', '30m', 'Best Seller', 'Iridescent mother-of-pearl dial framed in alternating two-tone links.', 'The Luna Pearl reflects soft opalescent hues from its natural mother-of-pearl dial. Completed with a dual-finish jubilee-style metal band that doubles as fine jewelry.', 97, 'Exquisite two-tone versatility coordinates effortlessly with both gold and silver jewelry collections.', 15, TRUE),
('WRT-010', '10', 'brand-vela', 'VELA', 'Roseline', 6499.00, 8299.00, 4.8, 140, '/assets/products/watch-10.png', 'cat-women', 'Women', 'Women', 'Quartz', 'Fashion', '36mm', 'Powder Pink Leather', 'Pastel Rose', 'Rose Gold PVD Steel', '30m', 'Trending', 'Soft blush undertones and sculpted rose gold lugs.', 'Delicate yet resilient. The Roseline features a matte blush pink dial with slim diamond-cut hands and a buttery-soft Italian calfskin strap in complementary pastel tones.', 93, 'Gentle pastel palette pairs naturally with spring/summer florals and light neutral wardrobes.', 15, TRUE),
('WRT-011', '11', 'brand-vela', 'VELA', 'Elara Silver', 4999.00, 6299.00, 4.7, 89, '/assets/products/watch-11.png', 'cat-women', 'Women', 'Women', 'Quartz', 'Minimal', '36mm', 'Silver Milanese Mesh', 'Pure Silver Sunburst', 'Stainless Steel', '30m', 'Clean Style', 'Ultra-slim profile that sits like a second skin on delicate wrists.', 'A masterclass in modern Scandinavian restraint. The Elara Silver measures just 6.8mm in case thickness, ensuring seamless sliding under knitwear and blouses.', 95, 'Clean silver architectural silhouette fits modern office dress codes with zero fuss.', 15, TRUE),
('WRT-012', '12', 'brand-vela', 'VELA', 'Celeste Blue', 5499.00, 6999.00, 4.8, 112, '/assets/products/watch-12.png', 'cat-women', 'Women', 'Women', 'Quartz', 'Casual', '34mm', 'Sky Blue Leather', 'Ice Blue Minimal', 'Polished Steel', '30m', 'New Arrival', 'Breezy glacial blue accents inspired by alpine skies.', 'Featuring a serene ice-blue dial that evokes calm clarity. The pastel powder-blue strap is secured with a polished steel pin buckle for all-day comfort.', 91, 'Bright pastel touch enlivens denim, white linen, and contemporary casual looks.', 15, TRUE),
('WRT-013', '13', 'brand-vela', 'VELA', 'Aurelia Gold', 8499.00, 10999.00, 4.9, 198, '/assets/products/watch-13.png', 'cat-women', 'Women', 'Women', 'Quartz', 'Premium', '32mm', '5-Link Gold Bracelet', 'Champagne Guilloché', '18K Gold PVD Steel', '50m', 'Luxury Pick', 'Fine jewelry watchmaking featuring an intricate guilloché dial texture.', 'The Aurelia Gold is a celebration of opulence. Its compact 32mm case is adorned with a textured sunburst dial and paired with a jewelry-style 5-link bracelet.', 96, 'Functions as a high-end statement bracelet that anchors evening gowns and cocktail attire.', 15, TRUE),
('WRT-014', '14', 'brand-vela', 'VELA', 'Ivory Pearl', 6999.00, 8799.00, 4.7, 94, '/assets/products/watch-14.png', 'cat-women', 'Women', 'Women', 'Quartz', 'Dress', '35mm', 'Cream Beige Leather', 'Warm Ivory', 'Gold PVD Steel', '30m', 'Staff Pick', 'Warm tonal neutral that radiates quiet luxury.', 'Warm ivory dial encased in a softly rounded champagne bezel, paired with a buttery cream leather band that develops a rich natural patina over time.', 94, 'Perfect tonal complement for the trending ''Quiet Luxury'' aesthetic and neutral cashmere palettes.', 15, TRUE),
('WRT-015', '15', 'brand-vela', 'VELA', 'Nova Mesh', 4799.00, 5999.00, 4.6, 82, '/assets/products/watch-15.png', 'cat-women', 'Women', 'Women', 'Quartz', 'Fashion', '36mm', 'Gunmetal Mesh', 'Midnight Black', 'Gunmetal Ion Plating', '30m', 'Trending', 'Moody gunmetal contrast designed for modern city streets.', 'Dark, sleek, and contemporary. The Nova Mesh marries gunmetal ion plating with an inky dial and polished indices that gleam under neon evening lights.', 90, 'Edgy metropolitan vibe that transitions seamlessly from co-working desk to rooftop drinks.', 15, TRUE),
('WRT-016', '16', 'brand-vela', 'VELA', 'Siena Rose', 5999.00, 7499.00, 4.8, 153, '/assets/products/watch-16.png', 'cat-women', 'Women', 'Women', 'Quartz', 'Classic', '35mm', 'Rose Gold Mesh', 'Sunray Rose', 'Rose Gold Steel', '30m', 'Popular', 'All-rose metallic harmony that glows warmly on all skin tones.', 'A continuous flow of warm rose gold from bezel to Milanese mesh. The dial features subtle radially brushed grain that catches daylight effortlessly.', 92, 'Universally flattering rose warmth that elevates basic tees as easily as cocktail dresses.', 15, TRUE),
('WRT-017', '17', 'brand-orbita', 'ORBITA', 'Core Black', 3999.00, 4999.00, 4.7, 165, '/assets/products/watch-17.png', 'cat-unisex', 'Unisex', 'Unisex', 'Quartz', 'Minimal', '38mm', 'Matte Silicone', 'Pitch Black', 'Polymer & Steel', '50m', 'Essential', 'Featherweight utilitarian watch built for effortless daily rotation.', 'ORBITA''s iconic Bauhaus-inspired daily watch. At just 42 grams, the Core Black features an ergonomic medical-grade silicone strap and high-contrast clean hands.', 93, 'Extremely lightweight and budget-friendly daily beater that maintains high design credibility.', 15, TRUE),
('WRT-018', '18', 'brand-orbita', 'ORBITA', 'Mono Steel', 4499.00, 5699.00, 4.8, 130, '/assets/products/watch-18.png', 'cat-unisex', 'Unisex', 'Unisex', 'Quartz', 'Minimal', '39mm', 'Brushed Steel Bracelet', 'Polar Silver', 'Stainless Steel', '50m', 'Popular', 'Industrial monochromatic purity inspired by brutalist architecture.', 'All-metal construction with horizontal satin brushing across case and integrated bracelet. A minimalist sculpture for your wrist.', 92, 'Brutalist all-steel aesthetic delivers maximum design punch per rupee.', 15, TRUE),
('WRT-019', '19', 'brand-orbita', 'ORBITA', 'Field Olive', 4999.00, 6299.00, 4.6, 78, '/assets/products/watch-19.png', 'cat-unisex', 'Unisex', 'Unisex', 'Quartz', 'Casual', '40mm', 'Tactical Olive Canvas', 'Army Olive', 'Matte Steel', '100m', 'Outdoor', 'Rugged military canvas strap with high-visibility dial markers.', 'Built for urban explorers and backcountry wanderers alike. The reinforced canvas webbing strap withstands rain, grit, and heavy use.', 88, 'Earthy military green works exceptionally well with denim, utility jackets, and hiking gear.', 15, TRUE),
('WRT-020', '20', 'brand-orbita', 'ORBITA', 'Urban Sand', 4799.00, 5999.00, 4.7, 92, '/assets/products/watch-20.png', 'cat-unisex', 'Unisex', 'Unisex', 'Quartz', 'Lifestyle', '39mm', 'Sand Nubuck Leather', 'Warm Dune Beige', 'Sandblasted Steel', '50m', 'Trending', 'Tactile desert hues inspired by coastal dunes and raw concrete.', 'Matte sandblasted case finish with zero glare. The soft nubuck band feels like velvet and acquires a beautiful personal patina over months of wear.', 91, 'Warm sand neutral pairs effortlessly with linen, oversized tees, and minimal streetwear.', 15, TRUE),
('WRT-021', '21', 'brand-orbita', 'ORBITA', 'Nightline', 5299.00, 6699.00, 4.8, 110, '/assets/products/watch-21.png', 'cat-unisex', 'Unisex', 'Unisex', 'Quartz', 'Minimal', '40mm', 'Black PVD Oyster Link', 'Midnight Matte', 'PVD Stainless Steel', '50m', 'Best Seller', 'Architectural stealth link watch with micro-beveled bezel edges.', 'Equipped with a solid-link metal bracelet coated in satin PVD black. Clean indices and needle hands ensure instant legibility without distraction.', 94, 'Versatile dark metal profile suitable for tech workplaces and nocturnal social outings.', 15, TRUE),
('WRT-022', '22', 'brand-orbita', 'ORBITA', 'Coast Blue', 4599.00, 5799.00, 4.6, 65, '/assets/products/watch-22.png', 'cat-unisex', 'Unisex', 'Unisex', 'Quartz', 'Casual', '41mm', 'Navy Ribbed Rubber', 'Ocean Cobalt', 'Stainless Steel', '100m', 'Water Ready', '100-meter waterproof companion for coastal getaways and water sports.', 'Engineered with a screw-down crown and hydrophobic ribbed silicone band that sheds water instantly. Crisp blue face matches the summer horizon.', 89, 'Genuine water resistance and sporty colorway make it the ideal companion for poolside and active weekends.', 15, TRUE),
('WRT-023', '23', 'brand-orbita', 'ORBITA', 'Studio White', 4299.00, 5499.00, 4.7, 84, '/assets/products/watch-23.png', 'cat-unisex', 'Unisex', 'Unisex', 'Quartz', 'Fashion', '38mm', 'Chalk White Leather', 'Optic White', 'Polished Steel', '30m', 'Clean Style', 'Pristine gallery-wall white with high-contrast obsidian typography.', 'Like a gallery exhibition on your wrist. High-contrast black hands float over a paper-white dial face, flanked by clean silver lugs and white topstitching.', 91, 'Striking monochrome contrast that stands out against dark winter jackets or bright summer outfits.', 15, TRUE),
('WRT-024', '24', 'brand-orbita', 'ORBITA', 'Slate Mesh', 5499.00, 6899.00, 4.8, 105, '/assets/products/watch-24.png', 'cat-unisex', 'Unisex', 'Unisex', 'Quartz', 'Minimal', '40mm', 'Anthracite Mesh', 'Graphite Grey', 'Ion-Plated Steel', '50m', 'Popular', 'Understated smoke-grey tonal palette with magnetic Milanese closure.', 'Occupying the sophisticated middle ground between harsh black and bright silver. The graphite brushed dial creates subtle depth without heavy shadows.', 93, 'Anthracite grey tone is universally compatible with business attire and modern casual styling.', 15, TRUE),
('WRT-025', '25', 'brand-vanta', 'VANTA', 'Apex Chrono', 9999.00, 12999.00, 4.9, 220, '/assets/products/watch-25.png', 'cat-men', 'Men', 'Men', 'Quartz', 'Chronograph', '44mm', 'Solid Rose & Black Bracelet', 'Multi-layered Chrono', '316L Stainless Steel', '100m', 'Top Seller', 'Motor-inspired high-speed timing with rose gold knurled crown.', 'A powerhouse wrist presence. The Apex Chrono features a multi-tiered dial with textured sub-registers, tachymeter scale, and tactile piston pushers for track timing.', 95, 'Bold mechanical architecture delivers commanding presence for business leaders and motorsport enthusiasts.', 15, TRUE),
('WRT-026', '26', 'brand-vanta', 'VANTA', 'Racer Black', 7999.00, 9999.00, 4.7, 145, '/assets/products/watch-26.png', 'cat-men', 'Men', 'Men', 'Quartz', 'Sport', '43mm', 'Perforated Racing Leather', 'Carbon Black & Red', 'Black DLC Steel', '100m', 'Sport Pick', 'High-octane red accents with breathable rally-hole strap.', 'Inspired by vintage endurance racing steering wheels. Breathable perforated black leather with scarlet edge-paint, housing a high-accuracy chronograph movement.', 91, 'Dynamic racing aesthetic injects energy into dark denim, leather jackets, and weekend track days.', 15, TRUE),
('WRT-027', '27', 'brand-vanta', 'VANTA', 'Velocity Steel', 8499.00, 10499.00, 4.8, 160, '/assets/products/watch-27.png', 'cat-men', 'Men', 'Men', 'Quartz', 'Sport', '42mm', 'Stainless Steel Oyster', 'Sunray Cobalt Blue', 'Stainless Steel', '100m', 'Trending', 'Vibrant blue sunray face enclosed in rugged bevelled steel shoulders.', 'The classic luxury sport archetype re-imagined. Sapphire-coated mineral glass protects an intense cobalt dial with luminescent hands that glow green in darkness.', 94, 'Versatile luxury sports watch profile that dresses up with a blazer and down with swim trunks.', 15, TRUE),
('WRT-028', '28', 'brand-vanta', 'VANTA', 'Pulse Red', 6999.00, 8799.00, 4.6, 74, '/assets/products/watch-28.png', 'cat-unisex', 'Unisex', 'Unisex', 'Quartz', 'Unisex', '41mm', 'Crimson Silicone', 'Ruby Sunburst', 'Anodized Black Steel', '50m', 'Bold Color', 'Unapologetic scarlet dial designed for bold fashion statements.', 'A head-turning statement watch. Saturated crimson dial flanked by a dark matte case and matching flexible silicone strap that withstands rain and gym sweat.', 87, 'High-contrast visual centerpiece for creative professionals who dress in predominantly black or monochrome.', 15, TRUE),
('WRT-029', '29', 'brand-vanta', 'VANTA', 'Trail Green', 7499.00, 9299.00, 4.7, 88, '/assets/products/watch-29.png', 'cat-men', 'Men', 'Men', 'Quartz', 'Outdoor', '42mm', 'Woven Green Nylon', 'Forest Green', 'Bead-Blasted Steel', '100m', 'Outdoor', 'Mil-spec ballistic nylon with quick-drying moisture-wicking weave.', 'Engineered for durability on the trail. Heavy-gauge field hands, 100m water resistance, and a non-reflective matte bead-blasted stainless steel case.', 89, 'Utilitarian green tone harmonizes with wax jackets, flannels, and rugged outdoor excursions.', 15, TRUE),
('WRT-030', '30', 'brand-vanta', 'VANTA', 'Carbon X', 8999.00, 11299.00, 4.8, 135, '/assets/products/watch-30.png', 'cat-men', 'Men', 'Men', 'Quartz', 'Sport', '43mm', 'Solid Carbon PVD Steel', '3D Textured Carbon', 'PVD Coated 316L', '100m', 'Popular', 'Woven twill carbon texture dial under scratch-resistant sapphire.', 'The dial captures light across hundreds of micro-facets mimicking woven carbon fiber. Fitted on a stealth black link bracelet with a concealed butterfly clasp.', 92, 'High-tech composite feel ideal for enthusiasts who value modern materials and industrial design.', 15, TRUE),
('WRT-031', '31', 'brand-norden', 'NORDEN', 'Automatic One', 16999.00, 21999.00, 4.9, 340, '/assets/products/watch-31.png', 'cat-men', 'Men', 'Men', 'Automatic', 'Automatic', '41mm', 'Solid 3-Link Steel', 'Deep Royal Sunburst', 'Surgical 316L Steel', '100m', 'Luxury Automatic', 'Self-winding 24-jewel Japanese mechanical movement with 42h reserve.', 'The pinnacle of everyday mechanical luxury. No battery required; winds automatically with your natural wrist motion. Sapphire crystal front and rear, high-beat second hand sweep.', 99, 'Highest recommendation for the classic luxury watch collector: mechanical integrity, stunning blue dial, and lifetime durability.', 15, TRUE),
('WRT-032', '32', 'brand-norden', 'NORDEN', 'Skeleton Arc', 19999.00, 24999.00, 5, 410, '/assets/products/watch-32.png', 'cat-men', 'Men', 'Men', 'Automatic', 'Automatic', '42mm', 'Polished Steel Bracelet', 'Open-worked Skeleton', '316L Stainless Steel', '50m', 'Masterpiece', 'Exhibition open-worked dial showcasing beating balance wheel and gears.', 'A mechanical sculpture. The skeletonized caliber reveals the rhythmic pulse of the hairspring and intricate gear train through double anti-reflective sapphire glass.', 98, 'Ultimate conversational horological statement that celebrates centuries of mechanical watchmaking art.', 15, TRUE),
('WRT-033', '33', 'brand-norden', 'NORDEN', 'Midnight Auto', 17999.00, 22499.00, 4.8, 195, '/assets/products/watch-33.png', 'cat-men', 'Men', 'Men', 'Automatic', 'Automatic', '41mm', 'Black Italian Leather', 'Lacquered Jet Black', 'Surgical Stainless Steel', '50m', 'Collector', 'Glossy black lacquer dial with razor-thin rhodium indices and rotor sweep.', 'Deep black enamel lacquer dial paired with hand-stitched Tuscan leather. The decorated mechanical rotor sweeps smoothly across the rear exhibition window.', 95, 'Epitome of sartorial discretion: pristine black-tie styling powered by traditional horology.', 15, TRUE),
('WRT-034', '34', 'brand-norden', 'NORDEN', 'Heritage 38', 15999.00, 19999.00, 4.9, 180, '/assets/products/watch-34.png', 'cat-men', 'Men', 'Men', 'Automatic', 'Classic', '38mm', 'Tan Horween Leather', 'Vintage Warm Cream', 'Rose Gold PVD Steel', '50m', 'Heritage', 'Golden era 38mm proportions inspired by 1950s gentlemen''s chronometers.', 'At a restrained 38mm, the Heritage 38 slips under any cuff effortlessly. The box-domed sapphire crystal imparts subtle vintage distortion at oblique angles.', 96, 'Classic 38mm proportions are widely considered the golden ratio for tailored elegance and wrist balance.', 15, TRUE),
('WRT-035', '35', 'brand-norden', 'NORDEN', 'Open Heart', 14999.00, 18999.00, 4.8, 165, '/assets/products/watch-35.png', 'cat-men', 'Men', 'Men', 'Automatic', 'Automatic', '40mm', 'Alligator-Grain Brown Leather', 'Parchment with Escapement Cutout', 'Rose Gold PVD', '50m', 'Luxury Pick', 'Dial aperture revealing the beating heart of the mechanical balance wheel.', 'The Open Heart allows you to observe the perpetual oscillation of the balance spring at 21,600 vibrations per hour while retaining a legible dress dial.', 93, 'Combines classic dress watch styling with the mesmerizing mechanical motion of an open balance wheel.', 15, TRUE),
('WRT-036', '36', 'brand-norden', 'NORDEN', 'Bronze Field', 18499.00, 22999.00, 4.9, 140, '/assets/products/watch-36.png', 'cat-men', 'Men', 'Men', 'Automatic', 'Outdoor', '42mm', 'Distressed Saddle Leather', 'Matte Olive Field', 'CuSn8 Marine Bronze', '100m', 'Collector', 'Solid marine bronze case that develops a unique natural patina with you.', 'Crafted from genuine marine-grade CuSn8 bronze, this watch oxidizes uniquely depending on your adventures, humidity, and wear, creating a one-of-a-kind heirloom.', 94, 'Evolving bronze patina offers unmatched storytelling and authenticity for rugged lifestyle connoisseurs.', 15, TRUE),
('WRT-037', '37', 'brand-pulse', 'PULSE', 'Pulse One', 5999.00, 7999.00, 4.7, 280, '/assets/products/watch-37.png', 'cat-men', 'Smart Watches', 'Unisex', 'Smart Digital', 'Smart', '44mm', 'Obsidian Silicone', 'Always-on AMOLED', 'Aerospace Aluminum', '50m', 'Best Seller', 'Ultra-crisp 1.43" AMOLED display with 7-day battery and biometric suite.', 'PULSE bridges smartwatch intelligence with luxury industrial aesthetics. Features continuous heart-rate, SpO2, sleep stages, 100+ workout modes, and notifications.', 95, 'Best recommendation for health-conscious professionals seeking smart connectivity without sacrificing wrist style.', 15, TRUE),
('WRT-038', '38', 'brand-pulse', 'PULSE', 'Pulse Active', 6999.00, 8999.00, 4.8, 190, '/assets/products/watch-38.png', 'cat-men', 'Smart Watches', 'Unisex', 'Smart Digital', 'Smart', '42mm', 'Lilac Fluororubber', 'Vibrant Curved AMOLED', 'Lightweight Aluminum', '50m', 'Fitness Pick', 'Sweatproof ergonomic band with dual-frequency GPS and recovery metrics.', 'Designed for runners, yogis, and fitness pioneers. The soft lilac fluororubber band resists moisture while the curved glass conforms comfortably during movement.', 92, 'Combines active tracking features with a gentle, refreshing colorway that looks great in the gym and at lunch.', 15, TRUE),
('WRT-039', '39', 'brand-pulse', 'PULSE', 'Pulse Pro', 8999.00, 11999.00, 4.9, 310, '/assets/products/watch-39.png', 'cat-men', 'Smart Watches', 'Men', 'Smart Digital', 'Smart', '46mm', 'Tactical Forest Green Band', 'High-Nit Sunlight AMOLED', 'Titanium & Ceramic', '50m', 'Flagship', 'Titanium bezel, offline maps, 14-day battery life, and Bluetooth calling.', 'The ultimate rugged smartwatch. Built with a tough titanium bezel ring, ceramic sensor backing, dual microphones for crisp wrist calls, and military-grade drop resistance.', 96, 'Uncompromising smartwatch durability with battery life that lasts through multi-day backcountry trails.', 15, TRUE),
('WRT-040', '40', 'brand-pulse', 'PULSE', 'Pulse Lite', 4999.00, 6499.00, 4.6, 150, '/assets/products/watch-40.png', 'cat-men', 'Smart Watches', 'Unisex', 'Smart Digital', 'Smart', '40mm', 'Cream Silicone', 'Retina Color Display', 'Reinforced Polymer', '30m', 'Value Pick', 'Featherweight 32g design with all essential fitness and wellness tracking.', 'Smartwatch essentials in a featherlight package. Soft cream band and bezel, customizable watch faces, step tracking, breathing exercises, and music controls.', 90, 'Lightweight, accessible entry point into smart health tracking with a clean, friendly aesthetic.', 15, TRUE)
